storage.rules:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    function isAdmin() {
      return get(/databases/(default)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    match /{allPaths=**} {
      allow read: if true;
    }

    match /services/{allPaths=**} {
      allow write: if request.auth != null && isAdmin();
    }

    match /products/{allPaths=**} {
      allow write: if request.auth != null && isAdmin();
    }

    match /users/{userId}/{allPaths=**} {
      allow write: if request.auth != null && request.auth.uid == userId;
    }
  }
}

firestore.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAdmin() {
      return request.auth != null && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    match /users/{userId} {
      allow get: if request.auth != null && (request.auth.uid == userId || isAdmin());
      allow list: if request.auth != null;
      allow create: if request.auth != null && request.auth.uid == request.resource.data.uid;
      allow update, delete: if request.auth != null && (request.auth.uid == userId || isAdmin());
    }
    match /services/{serviceId} {
      allow get, list: if true;
      allow create, update, delete: if isAdmin();
    }
    match /products/{productId} {
      allow get, list: if true;
      allow create, update, delete: if isAdmin();
    }
    match /pricing/{packageId} {
      allow get, list: if true;
      allow create, update, delete: if isAdmin();
    }
    match /survey-requests/{requestId} {
      allow create: if true;
      allow get, list, update, delete: if isAdmin();
    }
    match /settings/{settingId} {
        allow get, list: if request.auth != null;
        allow create, update, delete: if isAdmin();
    }
  }
}
